"use strict";(self.webpackChunksaferoceanave=self.webpackChunksaferoceanave||[]).push([[246],{246(e,a,n){n.r(a),n.d(a,{default:()=>t}),n.dn(t);var o=n(540);function t({ref:e=null}){return o.createElement("div",{ref:e,className:"markdown",dangerouslySetInnerHTML:{__html:'<style>\nh2, h3, h4, h5, h6 {\n    margin: 0;\n}\n</style>\n\n<h1>Upcoming meetings</h1>\n<h2><a href="https://luma.com/jh1w4hqy">K-Ingleside Ride Along &amp; Happy Hour</a></h2>\n<h3>Sun, October 25, 1:00pm-4:00pm</h3>\n<h4><a href="https://maps.app.goo.gl/Tr18JEk9bqMqELQG7">Philz Coffee</a>*, <a href="https://maps.app.goo.gl/cLis6euPjAfQC6Ua7">Charm Coffee</a>*, <a href="https://maps.app.goo.gl/6bBTNMhe6qRGjzJU9">Ocean Ale House</a>*</h4>\n<p><strong>*NOTE: This event is NOT affiliated with these businesses.</strong></p>\n<p>Join SF Transit Riders and Safer Ocean Avenue for a Ride Along of the\nK-Ingleside on Ocean Avenue!</p>\n<p><a href="https://luma.com/jh1w4hqy">Click here to learn more &amp; RSVP!</a></p>\n<h3>Ride along (1:00pm)</h3>\n<ul>\n<li>Meet at <a href="https://maps.app.goo.gl/Tr18JEk9bqMqELQG7">Philz Coffee</a> at 1:00pm.</li>\n<li>Take inbound K at Lee, record observations during ride.</li>\n<li>Get off at Junipero Serra and switch to outbound K, continue recording\nobservations.</li>\n<li>Stop at Victoria, walk to <a href="https://maps.app.goo.gl/cLis6euPjAfQC6Ua7">Charm Coffee</a>, quick debrief.</li>\n<li>Walk to Ocean Ale House, observe streetscape along the way.</li>\n</ul>\n<p>Making Ocean Avenue safer for pedestrians is a win-win for transit, safety, and\nthe community! The Ride Along will help Transit Riders hear directly from\ncommunity members and riders on what we should advocate for to improve the\nK-Ingleside.</p>\n<p><a href="https://luma.com/jh1w4hqy">Click here to learn more &amp; RSVP!</a></p>\n<h3>Happy hour (~2:30pm)</h3>\n<ul>\n<li>Meet at <a href="https://maps.app.goo.gl/6bBTNMhe6qRGjzJU9">Ocean Ale House</a> around ~2:30pm.</li>\n<li>Updates from the campaign.</li>\n<li>Talk about Prop H and RTM.</li>\n<li>Drink and mingle.</li>\n</ul>\n<p>The happy hour at Ocean Ale House is an opportunity to learn more about the two\nfunding measures on the November ballot, why those need to pass, and get to know\nother supporters or even hear from reasonable opposition.</p>\n<p><a href="https://luma.com/jh1w4hqy">Click here to learn more &amp; RSVP!</a></p>\n<hr>\n<p><a href="./past/">Click here to see past meetings.</a></p>\n'}})}}}]);
